package service

import (
	"fmt"
	"sync"
	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

var (
	users  = make(map[string]User)
	mutex  sync.RWMutex
)

// GetAllUsers returns a list of all users
func GetAllUsers() []User {
	mutex.RLock()
	defer mutex.RUnlock()
	var list []User
	for _, u := range users {
		list = append(list, u)
	}
	return list
}

// CreateUser creates a new user
func CreateUser(user User) (User, error) {
	mutex.Lock()
	defer mutex.Unlock()

	user.ID = uuid.New().String() // Using uuid for ID generation
	users[user.ID] = user
	return user, nil
}

// GetUserByID retrieves a user by their ID
func GetUserByID(id string) (User, bool) {
	mutex.RLock()
	defer mutex.RUnlock()
	u, ok := users[id]
	return u, ok
}

