package service_test

import (
	"testing"

	"tenkai/experiments/runs/20251217-180005_context_abtest/alt2_explicit_context/legacy_refactor/rep-1/internal/service"
)

func TestCreateUser(t *testing.T) {
	user := service.User{
		Name:  "Test User",
		Email: "test@example.com",
	}

	createdUser, err := service.CreateUser(user)
	if err != nil {
		t.Fatalf("CreateUser failed: %v", err)
	}

	if createdUser.ID == "" {
		t.Error("Expected user ID to be generated, got empty string")
	}

	if createdUser.Name != user.Name {
		t.Errorf("Expected user name %s, got %s", user.Name, createdUser.Name)
	}
}

func TestGetAllUsers(t *testing.T) {
	service.CreateUser(service.User{Name: "User 1", Email: "user1@example.com"})
	service.CreateUser(service.User{Name: "User 2", Email: "user2@example.com"})

	users := service.GetAllUsers()
	if len(users) < 2 {
		t.Errorf("Expected at least 2 users, got %d", len(users))
	}
}

func TestGetUserByID(t *testing.T) {
	user := service.User{
		Name:  "Find Me",
		Email: "findme@example.com",
	}
	createdUser, _ := service.CreateUser(user)

	foundUser, ok := service.GetUserByID(createdUser.ID)
	if !ok {
		t.Fatalf("GetUserByID failed to find user with ID %s", createdUser.ID)
	}

	if foundUser.Name != user.Name {
		t.Errorf("Expected user name %s, got %s", user.Name, foundUser.Name)
	}

	_, ok = service.GetUserByID("nonexistent-id")
	if ok {
		t.Error("Expected GetUserByID to not find a nonexistent user")
	}
}

package api_test

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"tenkai/experiments/runs/20251217-180005_context_abtest/alt2_explicit_context/legacy_refactor/rep-1/internal/api"
	"tenkai/experiments/runs/20251217-180005_context_abtest/alt2_explicit_context/legacy_refactor/rep-1/internal/service"
)

func TestUsersHandler_GetUsers(t *testing.T) {
	// Clear existing users to ensure test isolation
	service.ClearUsers()

	// Add a test user
	service.CreateUser(service.User{Name: "Test User", Email: "test@example.com"})

	req, err := http.NewRequest("GET", "/users", nil)
	if err != nil {
		t.Fatal(err)
	}

	rr := httptest.NewRecorder()
	handler := http.HandlerFunc(api.UsersHandler)

	handler.ServeHTTP(rr, req)

	if status := rr.Code; status != http.StatusOK {
		t.Errorf("handler returned wrong status code: got %v want %v",
			status, http.StatusOK)
	}

	expected := `[{"ID":"`
	if !strings.Contains(rr.Body.String(), expected) {
		t.Errorf("handler returned unexpected body: got %v want %v",
			rr.Body.String(), expected)
	}

	var users []service.User
	if err := json.Unmarshal(rr.Body.Bytes(), &users); err != nil {
		t.Fatalf("could not unmarshal response: %v", err)
	}
	if len(users) == 0 || users[0].Name != "Test User" {
		t.Errorf("Expected at least one user named 'Test User', got %+v", users)
	}
}

func TestUsersHandler_CreateUser(t *testing.T) {
	// Clear existing users to ensure test isolation
	service.ClearUsers()

	var jsonStr = []byte(`{"Name":"New User","Email":"new@example.com"}`)
	req, err := http.NewRequest("POST", "/users", bytes.NewBuffer(jsonStr))
	if err != nil {
		t.Fatal(err)
	}
	req.Header.Set("Content-Type", "application/json")

	rr := httptest.NewRecorder()
	handler := http.HandlerFunc(api.UsersHandler)

	handler.ServeHTTP(rr, req)

	if status := rr.Code; status != http.StatusCreated {
		t.Errorf("handler returned wrong status code: got %v want %v",
			status, http.StatusCreated)
	}

	expected := `{"ID":"`
	if !strings.Contains(rr.Body.String(), expected) {
		t.Errorf("handler returned unexpected body: got %v want substring %v",
			rr.Body.String(), expected)
	}

	var createdUser service.User
	if err := json.Unmarshal(rr.Body.Bytes(), &createdUser); err != nil {
		t.Fatalf("could not unmarshal response: %v", err)
	}
	if createdUser.Name != "New User" {
		t.Errorf("Expected created user name 'New User', got %s", createdUser.Name)
	}
}

func TestSpecificUserHandler_GetUserByID(t *testing.T) {
	// Clear existing users to ensure test isolation
	service.ClearUsers()

	// Add a test user
	userToFind, _ := service.CreateUser(service.User{Name: "Find Me", Email: "find@example.com"})

	req, err := http.NewRequest("GET", "/users/"+userToFind.ID, nil)
	if err != nil {
		t.Fatal(err)
	}

	rr := httptest.NewRecorder()
	handler := http.HandlerFunc(api.SpecificUserHandler)

	handler.ServeHTTP(rr, req)

	if status := rr.Code; status != http.StatusOK {
		t.Errorf("handler returned wrong status code: got %v want %v",
			status, http.StatusOK)
	}

	var foundUser service.User
	if err := json.Unmarshal(rr.Body.Bytes(), &foundUser); err != nil {
		t.Fatalf("could not unmarshal response: %v", err)
	}
	if foundUser.ID != userToFind.ID || foundUser.Name != userToFind.Name {
		t.Errorf("Expected to find user %+v, got %+v", userToFind, foundUser)
	}
}

func TestSpecificUserHandler_NotFound(t *testing.T) {
	// Clear existing users to ensure test isolation
	service.ClearUsers()

	req, err := http.NewRequest("GET", "/users/nonexistent-id", nil)
	if err != nil {
		t.Fatal(err)
	}

	rr := httptest.NewRecorder()
	handler := http.HandlerFunc(api.SpecificUserHandler)

	handler.ServeHTTP(rr, req)

	if status := rr.Code; status != http.StatusNotFound {
		t.Errorf("handler returned wrong status code: got %v want %v",
			status, http.StatusNotFound)
	}
}

